pp = []
i = 1
for sp, (fl, fh) in feeds.items():
    for cn, c in costs.items():
        for inc in (1, 2, 5):
            gap = (c - yeast_bulk) * inc / 100
            pp.append(dict(scenario_id=f'FBA-PP-{i:02d}', species=sp, t2_cost_case=cn, t2_cost_usd_per_t=c,
                comparator='imported bulk inactive yeast, 2025 (FOB)', comparator_price_usd_per_t=yeast_bulk, inclusion_pct=inc,
                extra_cost_usd_per_t_feed=round(gap, 1), feed_price_usd_per_t=f'{fl} to {fh}',
                gain_needed_pct_of_feed_cost=f'{gap/fh*100:.1f} to {gap/fl*100:.1f}',
                source_ids='FBA-17; FM-04; COST-43; COST-44', evidence_label='VN-direct', confidence='Low', demand_evidence_type='inferred',
                notes='Our calculation: (T2 cost minus bulk yeast price) x inclusion / feed price; the gain is the extra feed-cost saving (for example feed conversion or survival) a head-to-head trial must show over commodity yeast'))
            i += 1
for cn, c in costs.items():
    pp.append(dict(scenario_id=f'FBA-PP-{i:02d}', species='any', t2_cost_case=cn, t2_cost_usd_per_t=c,
        comparator='imported specialty yeast products, 2025 (FOB, unit value USD 2 per kg or more)', comparator_price_usd_per_t=yeast_spec, inclusion_pct='',
        extra_cost_usd_per_t_feed='', feed_price_usd_per_t='', gain_needed_pct_of_feed_cost=f'none: T2 cost is USD {yeast_spec - c:,} per t below the specialty unit value',
        source_ids='FBA-17; COST-43; COST-44', evidence_label='VN-direct', confidence='Low', demand_evidence_type='inferred',
        notes='Specialty tier was only 464 t (USD 3.97 million) in 2025, half of it from Japan, probably not all feed; to compete here T2 must match branded yeast fractions on documented function'))
    i += 1
pp.append(dict(scenario_id=f'FBA-PP-{i:02d}', species='any', t2_cost_case='variable cost only (tolled; no capital, labour or land)', t2_cost_usd_per_t='883 to 1,905',
    comparator='imported bulk inactive yeast, 2025 (FOB)', comparator_price_usd_per_t=yeast_bulk, inclusion_pct='', extra_cost_usd_per_t_feed='', feed_price_usd_per_t='',
    gain_needed_pct_of_feed_cost='Variable cost alone spans the bulk yeast price',
    source_ids='COST-01; COST-06; COST-16; COST-32; COST-33; FM-01; FBA-17', evidence_label='VN-direct', confidence='Low', demand_evidence_type='inferred',
    notes='Our calculation from the app-i cost lines: carbon 600 to 1,100, nitrogen 72 to 145, minerals 50 to 150, electricity 58 to 117, cooling 7 to 117, steam 78 to 218, water 18 to 58 USD per t of product'))
write('data_t2_price_per_performance.csv', pp)
print(len(reg), len(std), len(pp))
